    10	import br.com.pousadamarealta.reservas.persistence.MessageRepository;
    11	import br.com.pousadamarealta.reservas.persistence.ReservationRepository;
    12	import br.com.pousadamarealta.reservas.persistence.RoomRepository;
    13	import br.com.pousadamarealta.reservas.persistence.Schema;
    14	import br.com.pousadamarealta.reservas.service.ReportService;
    15	import br.com.pousadamarealta.reservas.service.ReservationService;
    16	import br.com.pousadamarealta.reservas.web.Routes;
    17	
    18	/** Monta o sistema. */
    19	public final class App {
    20	    private App() {}
    21	
    22	    public static Javalin create(Database db) {
    23	        Schema.create(db);
    24	
    25	        RoomRepository rooms = new RoomRepository(db);
    26	        ReservationRepository reservations = new ReservationRepository(db);
    27	        MessageRepository messages = new MessageRepository(db);
    28	
    29	        // Quem é avisado dos eventos da reserva. Para incluir (ou tirar) alguém, como o restaurante ou o
    30	        // transfer, basta escrever um EventSubscriber e registrá-lo aqui; o resto do sistema não muda.
    31	        EventBus events = new EventBus();
    32	        events.subscribe(new GuestNotifier(messages));
    33	        events.subscribe(new GovernanceNotifier(messages));
    34	        events.subscribe(new FinanceNotifier(messages));
    35	
    36	        ReservationService reservationService = new ReservationService(db, rooms, reservations, events);
    37	        ReportService reportService = new ReportService(db, rooms, reservations);
    38	
    39	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    40	        new Routes(reservationService, reportService, messages, db).register(app);
    41	        return app;
    42	    }
    43	}
