     9	/** Avisa o financeiro de pagamentos recebidos e de reembolsos a fazer. */
    10	public class FinanceNotifier implements EventSubscriber {
    11	    public static final String ADDRESS = "financeiro@pousadamarealta.com.br";
    12	
    13	    private final MessageGateway gateway;
    14	
    15	    public FinanceNotifier(MessageGateway gateway) {
    16	        this.gateway = gateway;
    17	    }
    18	
    19	    @Override
    20	    public void on(DomainEvent event) {
    21	        if (event instanceof ReservationConfirmed e) {
    22	            Reservation r = e.reservation();
    23	            gateway.sendEmail(ADDRESS, "Pagamento recebido - reserva " + r.id(),
    24	                    "Pagamento recebido da reserva nº " + r.id() + " (quarto " + e.room().number() + ").\n"
    25	                            + "Valor pago: " + Brl.money(r.amountPaid()));
    26	        } else if (event instanceof ReservationCancelled e && e.reservation().refund().signum() > 0) {
    27	            Reservation r = e.reservation();
    28	            gateway.sendEmail(ADDRESS, "Reembolso - reserva " + r.id(),
    29	                    "A reserva nº " + r.id() + " (quarto " + e.room().number() + ") foi cancelada.\n"
    30	                            + "Valor a devolver: " + Brl.money(r.refund()));
    31	        }
    32	    }
    33	}
