    13	        sb.append("Entrada: ").append(Brl.date(r.checkIn())).append(" | Saída: ").append(Brl.date(r.checkOut()))
    14	                .append(" | ").append(r.nights()).append(r.nights() == 1 ? " diária" : " diárias").append('\n');
    15	        sb.append("Diárias: ").append(Brl.money(r.subtotal())).append('\n');
    16	        if (r.discount().signum() > 0) {
    17	            sb.append("Desconto: ").append(Brl.money(r.discount())).append('\n');
    18	        }
    19	        sb.append("Total: ").append(Brl.money(r.total()));
    20	        return sb.toString();
