     1	package br.com.pousadamarealta.reservas.service;
     2	
     3	import br.com.pousadamarealta.reservas.domain.Money;
     4	import br.com.pousadamarealta.reservas.domain.Reservation;
     5	import br.com.pousadamarealta.reservas.domain.Room;
     6	import br.com.pousadamarealta.reservas.persistence.Database;
