    10	/** Formatação para texto: R$ 1.234,56 e 10/03/2027. */
    11	public final class Brl {
    12	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/uuuu");
    13	
    14	    private Brl() {}
    15	
    16	    public static String money(BigDecimal value) {
    17	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    18	        symbols.setGroupingSeparator('.');
    19	        symbols.setDecimalSeparator(',');
    20	        return "R$ " + new DecimalFormat("#,##0.00", symbols).format(value);
    21	    }
    22	
    23	    public static String date(LocalDate date) {
    24	        return DATE.format(date);
    25	    }
    26	
    27	    /** 11 dígitos viram 111.222.333-44; qualquer outra coisa fica como foi informada. */
    28	    public static String cpf(String cpf) {
    29	        if (cpf.matches("\\d{11}")) {
    30	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    31	        }
    32	        return cpf;
    33	    }
    34	}
