    18	public class ReportService {
    19	    private final Database db;
    20	    private final RoomRepository rooms;
    21	    private final ReservationRepository reservations;
    22	
    23	    public ReportService(Database db, RoomRepository rooms, ReservationRepository reservations) {
    24	        this.db = db;
    25	        this.rooms = rooms;
    26	        this.reservations = reservations;
    27	    }
    28	
    29	    public String occupancy(LocalDate night) {
    30	        return db.transaction(() -> {
    31	            List<Room> allRooms = rooms.findAll();
    32	            Map<Integer, Room> byNumber = allRooms.stream().collect(Collectors.toMap(Room::number, Function.identity()));
    33	            List<Reservation> occupying = reservations.findPaidOccupying(night);
    34	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    35	            for (Reservation r : occupying) {
    36	                csv.append(r.roomNumber()).append(',')
    37	                        .append(byNumber.get(r.roomNumber()).type()).append(',')
    38	                        .append(r.id()).append(',')
    39	                        .append(r.checkIn()).append(',')
    40	                        .append(r.checkOut()).append('\n');
    41	            }
    42	            csv.append("total,").append(occupying.size()).append('/').append(allRooms.size()).append('\n');
    43	            return csv.toString();
    44	        });
    45	    }
    46	
    47	    public String revenue(YearMonth month) {
    48	        return db.transaction(() -> {
    49	            List<Reservation> list = reservations.findWithRevenueStartingBetween(
    50	                    month.atDay(1), month.plusMonths(1).atDay(1));
    51	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    52	            BigDecimal sum = Money.ZERO;
    53	            for (Reservation r : list) {
    54	                BigDecimal kept = Money.round(r.amountPaid().subtract(r.refund() == null ? Money.ZERO : r.refund()));
    55	                sum = sum.add(kept);
    56	                csv.append(r.id()).append(',')
    57	                        .append(r.roomNumber()).append(',')
    58	                        .append(r.checkIn()).append(',')
    59	                        .append(r.checkOut()).append(',')
    60	                        .append(r.status()).append(',')
    61	                        .append(kept.toPlainString()).append('\n');
    62	            }
    63	            csv.append("total,").append(Money.round(sum).toPlainString()).append('\n');
    64	            return csv.toString();
    65	        });
    66	    }
    67	}
