    20	import static br.com.pousadamarealta.reservas.domain.PousadaException.Code.CAPACITY_EXCEEDED;
    21	import static br.com.pousadamarealta.reservas.domain.PousadaException.Code.RESERVATION_NOT_FOUND;
    22	import static br.com.pousadamarealta.reservas.domain.PousadaException.Code.ROOM_NOT_FOUND;
    23	import static br.com.pousadamarealta.reservas.domain.PousadaException.Code.ROOM_UNAVAILABLE;
    24	
    25	public class ReservationService {
    26	    private final Database db;
    27	    private final RoomRepository rooms;
    28	    private final ReservationRepository reservations;
    29	    private final EventBus events;
    30	
    31	    public ReservationService(Database db, RoomRepository rooms, ReservationRepository reservations, EventBus events) {
    32	        this.db = db;
    33	        this.rooms = rooms;
    34	        this.reservations = reservations;
    35	        this.events = events;
    36	    }
    37	
    38	    public List<Room> listRooms() {
    39	        return db.transaction(rooms::findAll);
    40	    }
    41	
    42	    public Reservation create(CreateReservation cmd) {
    43	        return db.transaction(() -> {
    44	            // o lock do quarto serializa reservas concorrentes dele, para a checagem de disponibilidade valer
    45	            Room room = rooms.find(cmd.roomNumber(), true)
    46	                    .orElseThrow(() -> new PousadaException(ROOM_NOT_FOUND, "Quarto " + cmd.roomNumber() + " não existe"));
    47	            if (cmd.guests() > room.capacity()) {
    48	                throw new PousadaException(CAPACITY_EXCEEDED,
    49	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    50	            }
    51	            if (reservations.existsOverlap(room.number(), cmd.checkIn(), cmd.checkOut())) {
    52	                throw new PousadaException(ROOM_UNAVAILABLE,
    53	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    54	            }
    55	            Quote quote = Pricing.quote(room, cmd.checkIn(), cmd.checkOut(), cmd.ratePlan());
    56	            return reservations.insert(new Reservation(0, room.number(), cmd.guestName(), cmd.guestEmail(),
    57	                    cmd.guestCpf(), cmd.checkIn(), cmd.checkOut(), cmd.guests(), cmd.ratePlan(), quote.nights(),
    58	                    quote.subtotal(), quote.discount(), quote.total(), ReservationStatus.PENDING, Money.ZERO, null));
    59	        });
    60	    }
    61	
    62	    public Reservation get(long id) {
    63	        return db.transaction(() -> load(id, false));
    64	    }
    65	
    66	    public Reservation confirm(long id) {
    67	        return db.transaction(() -> {
    68	            Reservation confirmed = load(id, true).confirm();
    69	            reservations.update(confirmed);
    70	            events.publish(new ReservationConfirmed(confirmed, roomOf(confirmed)));
    71	            return confirmed;
    72	        });
    73	    }
    74	
    75	    public Reservation cancel(long id) {
    76	        return db.transaction(() -> {
    77	            Reservation current = load(id, true);
    78	            Reservation cancelled = current.cancel();
    79	            reservations.update(cancelled);
    80	            if (current.status() == ReservationStatus.CONFIRMED) {
    81	                events.publish(new ReservationCancelled(cancelled, roomOf(cancelled)));
    82	            }
    83	            return cancelled;
    84	        });
    85	    }
    86	
    87	    public Reservation checkIn(long id) {
    88	        return db.transaction(() -> {
    89	            Reservation updated = load(id, true).checkInGuest();
    90	            reservations.update(updated);
    91	            return updated;
    92	        });
    93	    }
    94	
    95	    public Receipt checkOut(long id) {
    96	        return db.transaction(() -> {
    97	            Reservation updated = load(id, true).checkOutGuest();
    98	            reservations.update(updated);
    99	            return Receipt.of(updated, roomOf(updated));
   100	        });
   101	    }
   102	
   103	    public Receipt document(long id) {
   104	        return db.transaction(() -> {
   105	            Reservation reservation = load(id, false);
   106	            reservation.requirePaid();
   107	            return Receipt.of(reservation, roomOf(reservation));
   108	        });
   109	    }
   110	
   111	    private Reservation load(long id, boolean forUpdate) {
   112	        return reservations.find(id, forUpdate)
   113	                .orElseThrow(() -> new PousadaException(RESERVATION_NOT_FOUND, "Reserva " + id + " não existe"));
   114	    }
   115	
   116	    private Room roomOf(Reservation reservation) {
   117	        return rooms.find(reservation.roomNumber(), false).orElseThrow();
   118	    }
