     1	package br.com.pousadamarealta.reservas.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public final class Pricing {
     7	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
     9	
    10	    private Pricing() {}
    11	
    12	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. A data é a da noite. */
    13	    public static boolean isHighSeason(LocalDate night) {
    14	        int month = night.getMonthValue();
    15	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    16	    }
    17	
    18	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    19	        BigDecimal subtotal = Money.ZERO;
    20	        int nights = 0;
    21	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    22	            BigDecimal price = isHighSeason(night)
    23	                    ? Money.round(room.nightlyRate().multiply(HIGH_SEASON_FACTOR))
    24	                    : room.nightlyRate();
    25	            subtotal = Money.round(subtotal.add(price));
    26	            nights++;
    27	        }
    28	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    29	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    30	                : Money.ZERO;
    31	        BigDecimal total = Money.round(subtotal.subtract(discount));
    32	        return new Quote(nights, subtotal, discount, total);
    33	    }
    34	}
