63	    20	        int nights = 0;
64	    21	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
65	    22	            BigDecimal price = isHighSeason(night)
66	    23	                    ? Money.round(room.nightlyRate().multiply(HIGH_SEASON_FACTOR))
67	    24	                    : room.nightlyRate();
68	    25	            subtotal = Money.round(subtotal.add(price));
