    10	/** Pool de conexões e transações. Os repositórios usam a conexão da transação em andamento. */
    11	public class Database implements AutoCloseable {
    12	    private final HikariDataSource dataSource;
    13	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
    14	
    15	    public Database(String url, String user, String password) {
    16	        this(url, user, password, null);
    17	    }
    18	
    19	    public Database(String url, String user, String password, String schema) {
    20	        HikariConfig config = new HikariConfig();
    21	        config.setJdbcUrl(url);
    22	        config.setUsername(user);
    23	        config.setPassword(password);
    24	        if (schema != null) {
    25	            config.setSchema(schema);
    26	        }
    27	        config.setMaximumPoolSize(10);
    28	        // o banco pode demorar a ficar de pé quando tudo sobe junto
    29	        config.setInitializationFailTimeout(60_000);
    30	        this.dataSource = new HikariDataSource(config);
    31	    }
    32	
    33	    public Connection connection() {
    34	        Connection connection = current.get();
    35	        if (connection == null) {
    36	            throw new IllegalStateException("acesso ao banco fora de uma transação");
    37	        }
    38	        return connection;
    39	    }
    40	
    41	    public <T> T transaction(Supplier<T> work) {
    42	        if (current.get() != null) {
    43	            return work.get();
    44	        }
    45	        try (Connection connection = dataSource.getConnection()) {
    46	            connection.setAutoCommit(false);
    47	            current.set(connection);
    48	            try {
    49	                T result = work.get();
    50	                connection.commit();
    51	                return result;
    52	            } catch (RuntimeException | Error e) {
    53	                try {
    54	                    connection.rollback();
    55	                } catch (SQLException suppressed) {
    56	                    e.addSuppressed(suppressed);
    57	                }
    58	                throw e;
    59	            } finally {
    60	                current.remove();
    61	            }
    62	        } catch (SQLException e) {
    63	            throw new DataAccessException(e);
    64	        }
    65	    }
    66	
    67	    @Override
    68	    public void close() {
    69	        dataSource.close();
    70	    }
    71	}
