    14	import static br.com.pousadamarealta.reservas.domain.PousadaException.Code.INVALID_REQUEST;
    15	
    16	/** Valida o formato do que o site manda; tudo que está errado aqui é 400 INVALID_REQUEST. */
    17	final class RequestParser {
    18	    private static final int MIN_YEAR = 1900;
    19	    private static final int MAX_YEAR = 9999;
    20	
    21	    private RequestParser() {}
    22	
    23	    static CreateReservation createReservation(ObjectMapper mapper, byte[] body) {
    24	        JsonNode json;
    25	        try {
    26	            json = mapper.readTree(body);
    27	        } catch (IOException e) {
    28	            throw invalid("O corpo não é um JSON válido");
    29	        }
    30	        if (json == null || !json.isObject()) {
    31	            throw invalid("O corpo deve ser um objeto JSON");
    32	        }
    33	        int roomNumber = integer(json, "roomNumber");
    34	        String name = text(json, "guestName");
    35	        String email = text(json, "guestEmail");
    36	        String cpf = text(json, "guestCpf");
    37	        LocalDate checkIn = date(json, "checkIn");
    38	        LocalDate checkOut = date(json, "checkOut");
    39	        int guests = integer(json, "guests");
    40	        RatePlan plan;
    41	        try {
    42	            plan = RatePlan.valueOf(text(json, "ratePlan"));
    43	        } catch (IllegalArgumentException e) {
    44	            throw invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
    45	        }
    46	        if (!checkOut.isAfter(checkIn)) {
    47	            throw invalid("checkOut deve ser depois de checkIn");
    48	        }
    49	        if (guests < 1) {
    50	            throw invalid("guests deve ser pelo menos 1");
    51	        }
    52	        return new CreateReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
    53	    }
    54	
    55	    static LocalDate queryDate(String value) {
    56	        if (value == null) {
    57	            throw invalid("Informe date no formato AAAA-MM-DD");
    58	        }
    59	        return parseDate(value, "date");
    60	    }
    61	
    62	    static YearMonth queryMonth(String value) {
    63	        if (value == null) {
    64	            throw invalid("Informe month no formato AAAA-MM");
    65	        }
    66	        try {
    67	            YearMonth month = YearMonth.parse(value);
    68	            checkYear(month.getYear(), "month");
    69	            return month;
    70	        } catch (DateTimeException e) {
    71	            throw invalid("month deve estar no formato AAAA-MM");
    72	        }
    73	    }
    74	
    75	    private static String text(JsonNode json, String field) {
    76	        JsonNode node = json.get(field);
    77	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    78	            throw invalid("O campo " + field + " é obrigatório");
    79	        }
    80	        return node.asText();
    81	    }
    82	
    83	    private static int integer(JsonNode json, String field) {
    84	        JsonNode node = json.get(field);
    85	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    86	            throw invalid("O campo " + field + " é obrigatório e deve ser um número inteiro");
    87	        }
    88	        return node.asInt();
    89	    }
    90	
    91	    private static LocalDate date(JsonNode json, String field) {
    92	        return parseDate(text(json, field), field);
    93	    }
    94	
    95	    private static LocalDate parseDate(String value, String field) {
    96	        try {
    97	            LocalDate date = LocalDate.parse(value);
    98	            checkYear(date.getYear(), field);
    99	            return date;
   100	        } catch (DateTimeException e) {
   101	            throw invalid(field + " deve estar no formato AAAA-MM-DD");
   102	        }
   103	    }
   104	
   105	    private static void checkYear(int year, String field) {
   106	        if (year < MIN_YEAR || year > MAX_YEAR) {
   107	            throw invalid(field + " fora do intervalo aceito");
   108	        }
   109	    }
   110	
   111	    private static PousadaException invalid(String message) {
   112	        return new PousadaException(INVALID_REQUEST, message);
   113	    }
   114	}
